import java.util.Scanner;
public class JIfElseIfGrade2 {
	public static void main(String[] args) {
		//Al-khatwa 1: Qira'at harf al-daraja
		Scanner scan = new Scanner (System.in);
		System.out.println("Adkhil harf al-daraja bil-huruf al-kabira: "); 
		String grade = scan.next();
		scan.close();
		//Al-khatwa 2: Tahdid wa tabaa al-mantiqa al-raqmiya li harf al-daraja al-mudkhal
		if (grade.equals("A")) {
			System.out.println("Al-daraja musawi aw akbar min 90.");
		} else if (grade.equals("B")) {
			System.out.println("Al-daraja fi al-mantiqa [80-90).");
		} else if (grade.equals("C")) {
			System.out.println("Al-daraja fi al-mantiqa [70-80).");
		} else if (grade.equals("D")) {
			System.out.println("Al-daraja fi al-mantiqa [60-70).");
		} else {
			System.out.println("Al-daraja adna min 60.");
		}		
	}
}
